{
  "name": "opencode-codex-status",
  "version": "0.1.4",
  "description": "OpenCode TUI plugin that shows Codex quota in the sidebar.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/leo0o7/opencode-codex-status.git"
  },
  "bugs": {
    "url": "https://github.com/leo0o7/opencode-codex-status/issues"
  },
  "homepage": "https://github.com/leo0o7/opencode-codex-status#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "codex",
    "quota"
  ],
  "bin": {
    "opencode-codex-status": "dist/cli.js"
  },
  "exports": {
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "node scripts/build.mjs && tsc -p tsconfig.build.json",
    "prepublishOnly": "npm run typecheck && npm test && npm run build && npm run test:package",
    "test:package": "node scripts/smoke-package.mjs",
    "test": "vitest run",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.12",
    "@opentui/solid": "^0.3.0",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.29.7",
    "@types/node": "^24.0.0",
    "babel-preset-solid": "^1.9.12",
    "typescript": "^6.0.3",
    "vitest": "^4.1.7"
  }
}
